<script setup lang="ts">
import type { LinkRecord } from '~/types/api'
defineProps<{ links: LinkRecord[] }>()
defineEmits<{ delete: [link: LinkRecord]; toggle: [link: LinkRecord] }>()
const shortDate = (value: string | null) => value ? new Intl.DateTimeFormat('en', { dateStyle: 'medium' }).format(new Date(value)) : 'Never'
const status = (link: LinkRecord) => link.is_expired ? 'Expired' : link.is_active ? 'Active' : 'Disabled'
</script>
<template><div class="overflow-hidden rounded-lg border border-border bg-surface shadow-xs"><div class="hidden grid-cols-[1.1fr_1.5fr_.5fr_.6fr_.7fr_220px] gap-4 border-b border-border bg-canvas px-5 py-3 text-xs font-medium text-text-muted xl:grid"><span>Short link</span><span>Destination</span><span>Clicks</span><span>Status</span><span>Created</span><span class="text-right">Actions</span></div><article v-for="link in links" :key="link.id" class="grid gap-3 border-b border-border p-4 last:border-0 hover:bg-canvas/70 xl:grid-cols-[1.1fr_1.5fr_.5fr_.6fr_.7fr_220px] xl:items-center xl:gap-4 xl:px-5"><div class="min-w-0"><a :href="link.short_url" class="block truncate text-sm font-semibold text-brand" target="_blank" rel="noopener noreferrer">{{ link.short_code }}</a><p class="mt-0.5 truncate text-xs text-text-muted">{{ link.title || 'Untitled link' }}</p></div><p class="truncate text-xs text-text-secondary" :title="link.destination_url">{{ link.destination_url }}</p><p class="text-sm font-semibold">{{ link.clicks_count.toLocaleString() }}</p><span class="w-fit" :class="status(link) === 'Active' ? 'badge-success' : status(link) === 'Expired' ? 'badge-warning' : 'badge-danger'"><span class="size-1.5 rounded-full bg-current"/>{{ status(link) }}</span><p class="text-xs text-text-secondary">{{ shortDate(link.created_at) }}</p><div class="flex flex-wrap justify-start gap-1.5 xl:justify-end"><CopyButton :text="link.short_url"/><NuxtLink :to="`/dashboard/links/${link.id}`" class="btn-secondary h-8 px-3 text-xs">Edit</NuxtLink><NuxtLink :to="`/dashboard/links/${link.id}/analytics`" class="btn-secondary h-8 px-3 text-xs">Analytics</NuxtLink><button class="btn-ghost h-8 px-2 text-xs" type="button" @click="$emit('toggle', link)">{{ link.is_active ? 'Disable' : 'Enable' }}</button><button class="btn-ghost h-8 px-2 text-xs text-danger" type="button" @click="$emit('delete', link)">Delete</button></div></article></div></template>
